  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// A horror game a participant is making or has shipped.\nmodel Game {\n  id               String        @id @default(cuid())\n  title            String\n  pitch            String\n  engine           String?\n  sourceUrl        String?\n  playUrl          String?\n  status           GameStatus    @default(BREWING)\n  // Time: a linked Hackatime project, the last total read from it, and the\n  // participant's own figure when they've edited it (null = use Hackatime's).\n  hackatimeProject String?\n  trackedSeconds   Int?\n  claimedSeconds   Int?\n  shippedAt        DateTime?\n  // Review, set by an admin after shipping. Approving credits awardedPumpkins once.\n  reviewStatus     ReviewStatus?\n  reviewNote       String?\n  reviewedAt       DateTime?\n  reviewedBy       String?\n  awardedPumpkins  Int?\n  // Mirror in the program's Airtable (YSWS Project Submission), created on ship.\n  // Indexed, not @unique: the container's `prisma db push` refuses to add a unique constraint\n  // to an existing table, and the sync already guards against two games sharing a record.\n  airtableRecordId String?\n  airtableSyncedAt DateTime?\n  airtableError    String?\n  // The submission in Ari (Hack Club's review platform), sent on ship; decisions come back by webhook.\n  ariShipId        String?\n  ariSyncedAt      DateTime?\n  ariError         String?\n  // Ari's last review: the hours it approved and the rest of the review (decision, reviewer,\n  // justification fields), copied into Airtable for the Unified YSWS submission.\n  reviewHours      Float?\n  reviewDetail     Json?\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId String\n\n  screenshot Screenshot?\n\n  @@index([userId])\n  @@index([airtableRecordId])\n}\n\n// A game's screenshot, required to ship. Kept out of Game so listing games never loads image bytes.\nmodel Screenshot {\n  id        String   @id @default(cuid())\n  mime      String\n  size      Int\n  data      Bytes\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  game   Game   @relation(fields: [gameId], references: [id], onDelete: Cascade)\n  gameId String @unique\n}\n\nenum GameStatus {\n  BREWING\n  SHIPPED\n}\n\nenum ReviewStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// Every admin action, who did it and to what. Written in the same transaction as the change.\nmodel AdminAudit {\n  id            String   @id @default(cuid())\n  actorUserId   String\n  actorIdentity String\n  action        String\n  targetType    String\n  targetId      String\n  detail        Json?\n  createdAt     DateTime @default(now())\n\n  @@index([createdAt])\n  @@index([targetType, targetId])\n}\n\n// Necessary for Auth.js\nmodel Account {\n  id                       String  @id @default(cuid())\n  userId                   String\n  type                     String\n  provider                 String\n  providerAccountId        String\n  refresh_token            String?\n  access_token             String?\n  expires_at               Int?\n  token_type               String?\n  scope                    String?\n  id_token                 String?\n  session_state            String?\n  user                     User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  refresh_token_expires_in Int?\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel User {\n  id                 String         @id @default(cuid())\n  name               String?\n  email              String?        @unique\n  emailVerified      DateTime?\n  image              String?\n  // From Hack Club Auth (/api/v1/me). Phone, birthday and addresses are never stored here;\n  // they're read live from Hack Club Auth when needed.\n  hcIdentityId       String?        @unique\n  slackId            String?\n  yswsEligible       Boolean        @default(false)\n  verificationStatus String?\n  // Scare's currency. Earn rates are not set yet; the shop platform will own this.\n  pumpkins           Int            @default(0)\n  // First-run onboarding (the Carving Table): set when finished or skipped.\n  onboardedAt        DateTime?\n  tourSeenAt         DateTime?\n  accounts           Account[]\n  sessions           Session[]\n  games              Game[]\n  hackatime          HackatimeLink?\n  orders             Order[]\n  suggestions        Suggestion[]\n}\n\n// A Pumpkin Shop order. Price and name are copied from the catalog at the time of purchase,\n// so later catalog edits never change what someone already paid.\nmodel Order {\n  id        String      @id @default(cuid())\n  itemId    String\n  itemName  String\n  pumpkins  Int\n  usd       Float\n  details   String?\n  status    OrderStatus @default(PENDING)\n  adminNote String?\n  handledAt DateTime?\n  handledBy String?\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId String\n\n  @@index([userId])\n}\n\nenum OrderStatus {\n  PENDING\n  FULFILLED\n  CANCELLED\n  REJECTED\n}\n\n// A Hackatime account linked to a Scare user, for pulling coding time.\nmodel HackatimeLink {\n  id             String   @id @default(cuid())\n  hackatimeId    Int      @unique\n  accessToken    String\n  scope          String?\n  slackId        String?\n  githubUsername String?\n  trustLevel     String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId String @unique\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n/// An item a participant would like in the shop. Admins triage these at /admin/suggestions.\nmodel Suggestion {\n  id        String           @id @default(cuid())\n  name      String\n  link      String?\n  why       String?\n  status    SuggestionStatus @default(NEW)\n  adminNote String?\n  handledAt DateTime?\n  handledBy String?\n  createdAt DateTime         @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  userId String\n\n  @@index([userId])\n  @@index([status, createdAt])\n}\n\nenum SuggestionStatus {\n  NEW\n  ADDED\n  DECLINED\n}\n\n/// Ari webhook deliveries already handled. Ari retries a delivery until it gets a 2xx, so\n/// a delivery whose id is here is acknowledged without being applied again.\nmodel AriDelivery {\n  id        String   @id\n  event     String\n  gameId    String?\n  createdAt DateTime @default(now())\n}\n",
